export async function revealHistoricalNativeMessage({ execute, until, command, key }, text) {
  // Virtuoso's real scroller is keyboard-focusable. Native paging exercises
  // normal PageUp/PageDown scrolling until the receipt footer clears the log's
  // clipping edges; an intersecting message body cannot certify a clipped badge.
  await until("restarted message log hydrated", () => execute("return !!document.querySelector('[role=log]');"));
  const log = await command("POST", "/element", { using: "css selector", value: '[role="log"]' });
  await command("POST", `/element/${log["element-6066-11e4-a52e-4f735466cecf"]}/click`, {});
  try { await until("historical message receipt visibly rendered after native paging", async () => {
    const state = await execute("const e=Array.from(document.querySelectorAll('[data-testid=message-bubble]')).find(e=>e.textContent.includes(arguments[0])),r=e?.getBoundingClientRect(),l=document.querySelector('[role=log]')?.getBoundingClientRect(),badges=e?.querySelectorAll('[data-delivery]'),b=badges?.length===1?badges[0].getBoundingClientRect():null;const top=Math.max(0,l?.top),bottom=Math.min(innerHeight,l?.bottom),left=Math.max(0,l?.left),right=Math.min(innerWidth,l?.right);const visible=!!r&&!!l&&r.width>0&&r.height>0&&(badges?.length?!!b&&b.width>0&&b.height>0&&b.top>=top&&b.bottom<=bottom&&b.left>=left&&b.right<=right:r.bottom>top&&r.top<bottom&&r.right>left&&r.left<right);return {visible,down:!!l&&(b?b.top>=top&&b.bottom>bottom:r?.top>=bottom)};", [text]);
    if (state.visible) return true;
    assert.equal(await execute("return document.activeElement===document.querySelector('[role=log]');"), true, "native paging targets the focused message log");
    await key(state.down ? "\uE00F" : "\uE00E");
    return false;
  }); } catch (error) {
    const state = await execute("const log=document.querySelector('[role=log]'),bubbles=Array.from(document.querySelectorAll('[data-testid=message-bubble]'));return {count:bubbles.length,tails:bubbles.slice(-3).map(e=>e.textContent.slice(-120)),scrollTop:log?.scrollTop,scrollHeight:log?.scrollHeight,clientHeight:log?.clientHeight,targetInDom:bubbles.some(e=>e.textContent.includes(arguments[0]))};", [text]);
    throw new Error(`${error.message}; native history state ${JSON.stringify({ ...state, target: text })}`);
  }
}

export function nativeMinimumWindowRequest(defaultRect, defaultViewport) {
  const width = defaultRect.width - defaultViewport.width, height = defaultRect.height - defaultViewport.height;
  assert.ok(Number.isFinite(width) && Number.isFinite(height) && width >= 0 && height >= 0, `native window chrome must be measured from valid outer/client dimensions: ${JSON.stringify({ outer: defaultRect, client: defaultViewport })}`);
  return { width: 760 + width, height: 520 + height };
}

export function nativeSettingsTargets(defaultRect, defaultViewport, minimumViewport) {
  for (const rect of [defaultRect, defaultViewport, minimumViewport]) {
    assert.ok(Number.isFinite(rect.width) && Number.isFinite(rect.height) && rect.width >= 760 && rect.height >= 520, "native layout needs a valid minimum-sized desktop viewport");
  }
  assert.ok(defaultViewport.width > minimumViewport.width || defaultViewport.height > minimumViewport.height, "default and minimum native layout tiers must differ");
  return [
    { name: "defaultLayout", request: { width: defaultRect.width, height: defaultRect.height }, viewport: defaultViewport },
    { name: "minimumLayout", request: nativeMinimumWindowRequest(defaultRect, defaultViewport), viewport: minimumViewport },
  ];
}

export async function settledSignedInSession(c, owner) {
  return c.until("signed-in backend and rendered shell ready", async () => {
    const identity = await c.observe("owner_node_identity", { owner });
    if (identity.owner !== owner) return false;
    const shellReady = await c.execute("return !!document.querySelector('[data-testid=chat-shell] main.conversation-canvas')&&!document.querySelector('[data-testid=chat-shell] main .animate-spin');");
    return shellReady && { owner, backendReady: true, shellReady: true };
  });
}

export async function settledIncomingAttachment(c, fileConv, fileName, backendReady = false) {
  return c.until("incoming attachment complete in backend and rendered card", async () => {
    const status = (await c.observe("file_statuses", { fileConvs: [fileConv] })).find(row => row.file_conv === fileConv);
    backendReady ||= status?.ready === true;
    if (!backendReady) return false;
    const rendered = await c.execute("const e=Array.from(document.querySelectorAll('[data-testid=message-bubble]')).find(e=>e.textContent.includes(arguments[0])),action=e?.querySelector('button[title][aria-label]');return !!e&&!e.querySelector('[data-testid=receive-file],[role=progressbar]')&&!!action&&!action.disabled&&!action.hasAttribute('data-download-error')&&action.getBoundingClientRect().width>0;", [fileName]);
    return rendered && { backendReady: true, renderedComplete: true };
  });
}

export async function settledPrivacyMode(c) {
  await c.until("invisible confirmation fully dismissed", () => c.execute("return !document.querySelector('[data-testid=invisible-confirm]');"));
  await c.settledDialog("settings-dialog");
  return { confirmationDismissed: true, dialogSettled: true };
}

export async function wrongPasswordCheckpoint(c) {
  const name = "auth-logout-wrong-password";
  const errorCapture = await c.captureAuthError(`${name}-error`, { kind: "auth-error", texts: c.invalidCredentialTexts });
  const sessionReady = await c.login(c.userName);
  await c.passed(name, { sessionReady, loggedOut: true, wrongPasswordRejected: true, signinRestored: true, invalidCredentialsKey: "login.invalidCredentials", errorCapture }, [errorCapture]);
}
