// Runtime assertions against the owned native webview, real CLI, and read-only
// production observations. This module does not replace any application IPC.
import assert from "node:assert/strict";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";

export function writeChildCommand(child, text) {
  return new Promise((resolve, reject) => {
    const stream = child.stdin;
    if (!stream || stream.destroyed || !stream.writable || stream.writableEnded) {
      reject(new Error("Owned child stdin is not writable"));
      return;
    }
    stream.once("error", reject);
    try {
      stream.write(text, error => {
        if (error) reject(error);
        else { stream.removeListener("error", reject); resolve(); }
      });
    } catch (error) { reject(error); }
  });
}

/** Keep attachment output inside the disposable profile, independent of OS home folders. */
export async function prepareNativeDownloadFixture({ fixture, owner, invoke }) {
  assert.ok(owner, "native download setup requires the signed-in fixture owner");
  const directory = join(fixture, "downloads");
  await mkdir(directory, { recursive: true });
  const expectedAccount = await invoke("account_id", {});
  assert.match(typeof expectedAccount === "string" ? expectedAccount : "", /^[0-9a-f]{32}$/, "native download setup requires the current account");
  const settings = await invoke("get_app_settings", { owner });
  await invoke("set_app_settings", { owner, expectedAccount, settings: { ...settings, download_dir: directory }, patch: { download_dir: directory } });
  assert.equal((await invoke("get_app_settings", { owner })).download_dir, directory, "production settings retain the owned download directory");
  return directory;
}

/** A successful automatic export is durable evidence even after transient chunks retire. */
export async function verifyNativeAttachmentDownload(c, path, expected) {
  return c.until("incoming attachment exact decrypted download bytes available", async () => {
    let actual;
    try { actual = await readFile(path); }
    catch (error) { if (error.code === "ENOENT") return false; throw error; }
    assert.deepEqual(actual, expected, "native download must contain the complete original bytes");
    return true;
  });
}

