interface AuthState {
  user: UserInfo | null;
  createdUsername: string | null;
  newAccount: boolean;
  savedSession: SavedSessionStatus | null;
  dismissProtection: () => void;
  dismissBackupReminder: () => void;
  retrySavedSession: () => Promise<boolean>;
  generation: number;
  operation: number;
  /** True until live-session restoration or cold saved login resolves; gates the
   * unlocking splash so an authenticated session does not flash the login screen. */
  booting: boolean;
  /** Hide ownerless login settings while the native session is being retired. */
  loggingOut: boolean;
  loading: boolean;
  error: string | null;
  clearError: () => void;
  /** Restore the live native session, or cold saved login when "stay signed in" is on. */
  tryAutoLogin: () => Promise<void>;
  login: (username: string, password: string) => Promise<boolean>;
  register: (username: string, password: string) => Promise<boolean>;
  enrollDevice: (
    enrollmentId: string,
    sourceId: string,
    code: string,
    includeHistory: boolean,
  ) => Promise<boolean>;
  /** Change the editable display name (nickname). Returns true on success. */
  rename: (newDisplayName: string) => Promise<boolean>;
  logout: () => Promise<void>;
}

/** All successful native authentication paths publish through one generation owner. */
async function enterAuthenticatedSession(
  request: () => Promise<LoginResult>,
  newAccount: boolean,
  set: (state: Partial<AuthState>) => void,
  get: () => AuthState,
): Promise<boolean> {
  const generation = get().generation + 1;
  const operation = get().operation + 1;
  set({
    generation,
    operation,
    user: null,
    newAccount: false,
    savedSession: null,
    loading: true,
    loggingOut: false,
    error: null,
  });
  try {
    const res = await request();
    if (get().generation !== generation || get().operation !== operation)
      return false;
    if (!res.success || !res.user) throw new Error("Unable to sign in");
    set({
      user: res.user,
      loading: false,
      booting: false,
      newAccount,
      createdUsername: null,
      savedSession: res.saved_session ?? null,
    });
    return true;
  } catch (e) {
    if (get().generation !== generation || get().operation !== operation)
      return false;
    set({ error: errMsg(e), loading: false });
    return false;
  }
}

