    pub(crate) fn current<T>(
        &self,
        operation: impl FnOnce(&mut SessionInfo) -> T,
    ) -> Result<T, String> {
        self.session.matching(&self.lease, |info| {
            if !self.node.ticket_current(self.ticket) {
